                "所有 DocBody 中的 Signatures 引用都应被移除，实际内容：" + updated);
        assertEquals(2, countOpeningTags(updated, "DocBody"),
                "DocBody 节点本身不应被移除");
        assertTrue(updated.contains("Doc_0/Document.xml") && updated.contains("Doc_1/Document.xml"),
