     * 独立的读取器与虚拟容器，处理完毕后由调用者负责持久化（flush）。
     */
    private void runHandler() throws IOException {
        Path root = workDir.toAbsolutePath();
        try (OFDReader reader = new OFDReader(root.toString(), false)) {
            assertNotNull(reader.getWorkDir(), "工作目录不应为空");
            OFDDir ofdDir = new OFDDir(root);
            handler.handle(reader, ofdDir);
            // 处理器只修改虚拟容器，持久化由调用方完成
            ofdDir.flush();
        }
    }

    private void writeOfdXml(String signaturesElement) throws IOException {
        String xml = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n"
                + "<OFD Version=\"1.2\" DocType=\"OFD\">"
                + "<DocBody><DocInfo><DocID>id-0</DocID></DocInfo>"
                + "<DocRoot>Doc_0/Document.xml</DocRoot>"
                + signaturesElement
                + "</DocBody></OFD>";
        writeFile("OFD.xml", xml);
    }

    private void writeDocumentXml() throws IOException {
        writeFile("Doc_0/Document.xml", "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n"
                + "<Document><CommonData><MaxUnitID>4</MaxUnitID></CommonData>"
                + "<Pages><Page ID=\"1\" BaseLoc=\"Pages/Page_0/Content.xml\"/></Pages></Document>");
        writeFile("Doc_0/Pages/Page_0/Content.xml", "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n"
                + "<Page><Content/></Page>");
    }

    private void writeSignatures(String... signatureElements) throws IOException {
        StringBuilder sb = new StringBuilder();
        sb.append("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<Signatures>\n");
        for (String element : signatureElements) {
            sb.append(element).append('\n');
        }
        sb.append("</Signatures>");
        writeFile(SIGNS_DIR + "/Signatures.xml", sb.toString());
    }

    private void writeFile(String relativePath, String content) throws IOException {
        Path target = workDir.resolve(relativePath);
        Files.createDirectories(target.getParent());
        Files.write(target, content.getBytes(StandardCharsets.UTF_8));
    }

    private String readFile(String relativePath) throws IOException {
        return new String(Files.readAllBytes(workDir.resolve(relativePath)), StandardCharsets.UTF_8);
    }

    private String readOfdXml() throws IOException {
        return readFile("OFD.xml");
    }

    /**
     * 统计 XML 文本中指定名称元素（允许带命名空间前缀）的开始标签数量。
     */
    private static int countOpeningTags(String xml, String elementName) {
        java.util.regex.Matcher matcher = java.util.regex.Pattern
                .compile("<(?:[A-Za-z0-9_.-]+:)?" + elementName + "[\\s/>]")
                .matcher(xml);
        int count = 0;
        while (matcher.find()) {
            count++;
        }
        return count;
    }
}

