    private static void assertPageDimensions(Path ofd, float[][] expectedPdfPageSizes) throws IOException {
        try (OFDReader reader = new OFDReader(ofd)) {
            List<PageInfo> pages = reader.getPageList();
            assertEquals(expectedPdfPageSizes.length, pages.size(), "unexpected OFD page count");
            for (int i = 0; i < expectedPdfPageSizes.length; i++) {
                double expectedWidth = expectedPdfPageSizes[i][0] / PDF_USER_UNIT_PER_MM;
                double expectedHeight = expectedPdfPageSizes[i][1] / PDF_USER_UNIT_PER_MM;
                assertEquals(expectedWidth, pages.get(i).getSize().getWidth(), DIMENSION_TOLERANCE,
                        "unexpected width for page " + i);
                assertEquals(expectedHeight, pages.get(i).getSize().getHeight(), DIMENSION_TOLERANCE,
                        "unexpected height for page " + i);
            }
        }
    }

    private static Path createPdf(Path path, PageSpec... pages) throws IOException {
        try (PDDocument document = new PDDocument()) {
            PDDocumentOutline outline = new PDDocumentOutline();
            boolean hasBookmarks = false;

            for (PageSpec spec : pages) {
                PDPage page = new PDPage(new PDRectangle(spec.width, spec.height));
                page.setRotation(spec.rotation);
                document.addPage(page);

                if (spec.bookmarkTitle != null) {
                    PDPageXYZDestination destination = new PDPageXYZDestination();
                    destination.setPage(page);
                    destination.setLeft(10);
                    destination.setTop(20);

                    PDOutlineItem item = new PDOutlineItem();
                    item.setTitle(spec.bookmarkTitle);
                    item.setDestination(destination);
                    outline.addLast(item);
                    hasBookmarks = true;
                }
            }

            if (hasBookmarks) {
                document.getDocumentCatalog().setDocumentOutline(outline);
            }
            document.save(path.toFile());
        }
        return path;
    }

    private static Path createPdfWithEmbeddedFile(Path path, String attachmentName, byte[] content)
            throws IOException {
        try (PDDocument document = new PDDocument()) {
            document.addPage(new PDPage(new PDRectangle(120, 220)));

            PDEmbeddedFile embeddedFile = new PDEmbeddedFile(document, new ByteArrayInputStream(content));
            embeddedFile.setSubtype("text/plain");
            embeddedFile.setSize(content.length);

            PDComplexFileSpecification fileSpecification = new PDComplexFileSpecification();
            fileSpecification.setFile(attachmentName);
            fileSpecification.setFileUnicode(attachmentName);
            fileSpecification.setFileDescription("test attachment");
            fileSpecification.setEmbeddedFile(embeddedFile);

            Map<String, PDComplexFileSpecification> embeddedFileNames = new HashMap<>();
            embeddedFileNames.put(attachmentName, fileSpecification);
            PDEmbeddedFilesNameTreeNode embeddedFiles = new PDEmbeddedFilesNameTreeNode();
            embeddedFiles.setNames(embeddedFileNames);

            PDDocumentNameDictionary names = new PDDocumentNameDictionary(document.getDocumentCatalog());
            names.setEmbeddedFiles(embeddedFiles);
            PDDocumentCatalog catalog = document.getDocumentCatalog();
            catalog.setNames(names);

            document.save(path.toFile());
        }
        return path;
    }

    private static final class PageSpec {
        private final float width;
        private final float height;
        private final int rotation;
        private final String bookmarkTitle;

        private PageSpec(float width, float height) {
            this(width, height, 0, null);
        }

        private PageSpec(float width, float height, int rotation) {
            this(width, height, rotation, null);
        }

        private PageSpec(float width, float height, int rotation, String bookmarkTitle) {
            this.width = width;
            this.height = height;
            this.rotation = rotation;
            this.bookmarkTitle = bookmarkTitle;
        }
    }
}

