        Path ofd = tempDir.resolve(fileName);
        try (ZipOutputStream zos = new ZipOutputStream(Files.newOutputStream(ofd))) {
            putEntry(zos, "OFD.xml", OFD_XML);
            putEntry(zos, "Doc_0/Document.xml", documentXml(pageLayerContents.length));
            putEntry(zos, "Doc_0/PublicRes.xml", PUBLIC_RES);
            for (int i = 0; i < pageLayerContents.length; i++) {
                putEntry(zos, "Doc_0/Pages/Page_" + i + "/Content.xml", pageXml(pageLayerContents[i]));
            }
        }
        return ofd;
    }

    /**
     * 生成包含模板页（TemplatePage）的 OFD 文件，页面正文层由 pageLayerContent 提供，
     * 模板页层由 templateLayerContent 提供。
     */
    private Path writeOfdWithTemplate(String fileName, String templateLayerContent, String pageLayerContent)
            throws IOException {
        Path ofd = tempDir.resolve(fileName);
        String document = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n"
                + "<ofd:Document xmlns:ofd=\"http://www.ofdspec.org/2016\"><ofd:CommonData>"
                + "<ofd:PageArea><ofd:PhysicalBox>0 0 210 297</ofd:PhysicalBox></ofd:PageArea>"
                + "<ofd:PublicRes>PublicRes.xml</ofd:PublicRes><ofd:MaxUnitID>1000</ofd:MaxUnitID>"
                + "<ofd:TemplatePage ID=\"2\" BaseLoc=\"Tpls/Tpl_0/Content.xml\" ZOrder=\"Background\"/>"
                + "</ofd:CommonData><ofd:Pages>"
                + "<ofd:Page ID=\"10\" BaseLoc=\"Pages/Page_0/Content.xml\"/>"
                + "</ofd:Pages></ofd:Document>";
        String page = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n"
                + "<ofd:Page xmlns:ofd=\"http://www.ofdspec.org/2016\">"
                + "<ofd:Template TemplateID=\"2\" ZOrder=\"Background\"/>"
                + "<ofd:Content><ofd:Layer ID=\"2\">" + pageLayerContent + "</ofd:Layer></ofd:Content></ofd:Page>";
        try (ZipOutputStream zos = new ZipOutputStream(Files.newOutputStream(ofd))) {
            putEntry(zos, "OFD.xml", OFD_XML);
            putEntry(zos, "Doc_0/Document.xml", document);
            putEntry(zos, "Doc_0/PublicRes.xml", PUBLIC_RES);
            putEntry(zos, "Doc_0/Pages/Page_0/Content.xml", page);
            putEntry(zos, "Doc_0/Tpls/Tpl_0/Content.xml", pageXml(templateLayerContent));
        }
        return ofd;
    }

    // ------------------------------------------------------------------
    // 断言工具
