    private static void assertValidPosition(KeywordPosition position, int expectedPage, String expectedKeyword) {
        assertNotNull(position, "返回的关键字位置对象不应为 null");
        assertEquals(expectedPage, position.getPage(), "关键字所在页码不正确");
        assertEquals(expectedKeyword, position.getKeyword(), "关键字文本回填不正确");
        ST_Box box = position.getBox();
        assertNotNull(box, "关键字外接矩形不应为 null");
        assertNotNull(box.getTopLeftX(), "矩形左上角X不应为 null");
        assertNotNull(box.getTopLeftY(), "矩形左上角Y不应为 null");
        assertTrue(box.getWidth() > 0, "矩形宽度应大于0，实际为：" + box.getWidth());
        assertTrue(box.getHeight() > 0, "矩形高度应大于0，实际为：" + box.getHeight());
        assertTrue(Double.isFinite(box.getTopLeftX()) && Double.isFinite(box.getTopLeftY()),
                "矩形坐标应为有限值");
    }

    private static List<String> keywordsOf(List<KeywordPosition> positions) {
        List<String> keywords = new ArrayList<>();
        for (KeywordPosition position : positions) {
            keywords.add(position.getKeyword());
        }
        return keywords;
    }

    private static List<Integer> pagesOf(List<KeywordPosition> positions) {
        List<Integer> pages = new ArrayList<>();
        for (KeywordPosition position : positions) {
            pages.add(position.getPage());
        }
        return pages;
    }

