    @Test
    void keywordContainedInSingleTextCode_returnsExactBox() throws Exception {
        // Boundary 起点 (10,20)，TextCode 起点 (0,3)，每个字符水平前进 3mm，字号 3.0
        Path ofd = writeOfd("single.ofd",
                textObject(4, "10 20 50 10", "3.0", "3", "合同编号ABC"));

        try (OFDReader reader = new OFDReader(ofd)) {
            List<KeywordPosition> positions = KeywordExtractor.getKeyWordPositionList(
                    reader, new String[]{"ABC"}, null);

            assertEquals(1, positions.size(), "关键字 ABC 在文档中出现一次");
            KeywordPosition position = positions.get(0);
            assertValidPosition(position, 1, "ABC");

            ST_Box box = position.getBox();
            // 起始字符索引为 4 => 起点 X = Boundary.X + 4 * DeltaX = 10 + 12
            assertEquals(22d, box.getTopLeftX(), EPS, "关键字起始X坐标应等于Boundary偏移与字符偏移之和");
            // 宽度 = 字号 + (关键字长度-1) * DeltaX = 3 + 2 * 3
            assertEquals(9d, box.getWidth(), EPS, "关键字宽度应为字号与字符间距的累加");
            // Y 方向：文字基线 Y = 20 + 3 = 23，矩形顶部 = 基线 - 字体高度
            assertEquals(23d, box.getTopLeftY() + box.getHeight(), EPS, "矩形底边应位于文字基线位置");
        }
    }

    @Test
    void keywordAppearsTwiceInOneTextCode_returnsOnePositionPerOccurrence() throws Exception {
        Path ofd = writeOfd("twice.ofd",
                textObject(4, "10 40 50 10", "3.0", "3", "关键字关键字"));

        try (OFDReader reader = new OFDReader(ofd)) {
            List<KeywordPosition> positions = KeywordExtractor.getKeyWordPositionList(
                    reader, new String[]{"关键字"}, null);

            assertEquals(2, positions.size(), "同一文字定位中出现两次关键字应返回两个位置");
            assertValidPosition(positions.get(0), 1, "关键字");
            assertValidPosition(positions.get(1), 1, "关键字");
            assertEquals(10d, positions.get(0).getBox().getTopLeftX(), EPS, "第一次出现应位于文本起点");
            assertEquals(19d, positions.get(1).getBox().getTopLeftX(), EPS, "第二次出现应位于三个字符之后");
            assertTrue(positions.get(1).getBox().getTopLeftX() > positions.get(0).getBox().getTopLeftX(),
                    "后一次出现应位于前一次出现的右侧");
        }
    }

    @Test
    void multipleKeywords_returnPositionsInDocumentOrder() throws Exception {
        Path ofd = writeOfd("multiKeyword.ofd",
