    @Test
    void keywordSplitAcrossTextCodes_isMergedIntoOnePosition() throws Exception {
        Path ofd = writeOfd("splitPrefix.ofd",
                textObject(6, "57.16 170.84 21.17 7.81", "4.0", "4 4 4 4", "重庆市马")
                        + textObject(7, "78.33 170.84 12.70 7.81", "4.0", "4 4", "上融资"));

        try (OFDReader reader = new OFDReader(ofd)) {
            List<KeywordPosition> positions = KeywordExtractor.getKeyWordPositionList(
                    reader, new String[]{"重庆市马上融资"}, null);

            assertEquals(1, positions.size(), "跨文字定位的关键字应合并为一个位置");
            assertValidPosition(positions.get(0), 1, "重庆市马上融资");
            ST_Box box = positions.get(0).getBox();
            // 合并后的矩形应跨越两个文字对象（总宽度明显大于单个文字对象宽度）
            assertTrue(box.getWidth() > 21.17, "合并矩形宽度应大于第一个文字对象宽度，实际：" + box.getWidth());
            assertEquals(57.16d, box.getTopLeftX(), EPS, "合并矩形左边界应为第一个文字对象的左边界");
        }
    }

    @Test
    void keywordSuffixSplitAcrossTextCodes_isMergedIntoOnePosition() throws Exception {
        // 第一个文字对象只包含关键字的前缀（"合同号A" 中的 "A"），后续文字对象补全 "001"
        Path ofd = writeOfd("splitSuffix.ofd",
                textObject(8, "10 60 50 10", "3.0", "3 3 3 3", "合同号A")
                        + textObject(9, "30 60 50 10", "3.0", "3 3 3", "001"));

        try (OFDReader reader = new OFDReader(ofd)) {
            List<KeywordPosition> positions = KeywordExtractor.getKeyWordPositionList(
                    reader, new String[]{"A001"}, null);

            assertEquals(1, positions.size(), "后缀跨文字定位的关键字应合并为一个位置");
            assertValidPosition(positions.get(0), 1, "A001");
            ST_Box box = positions.get(0).getBox();
            // 起点越过 "合同号" 三个字符 => 10 + 3*3
            assertEquals(19d, box.getTopLeftX(), EPS, "合并矩形左边界应从关键字首字符开始");
            assertTrue(box.getWidth() > 9d, "合并矩形应覆盖第二个文字对象中的字符");
        }
    }

