    private Path twoPageDocument() throws IOException {
        return writeOfd("twoPages.ofd",
                textObject(4, "10 20 50 10", "3.0", "3", "报告编号R1"),
                textObject(4, "10 20 50 10", "3.0", "3", "报告编号R2"));
