    @Test
    void nullPages_searchesAllPages() throws Exception {
        Path ofd = twoPageDocument();
        try (OFDReader reader = new OFDReader(ofd)) {
            List<KeywordPosition> positions = KeywordExtractor.getKeyWordPositionList(
                    reader, new String[]{"报告"}, null);

            assertEquals(2, positions.size(), "未限定页码时应检索全部页面");
            assertEquals(Arrays.asList(1, 2), pagesOf(positions), "应分别在两页中命中");
            assertValidPosition(positions.get(0), 1, "报告");
            assertValidPosition(positions.get(1), 2, "报告");
        }
    }

    @Test
    void singlePageLimit_onlySearchesRequestedPage() throws Exception {
        Path ofd = twoPageDocument();
        try (OFDReader reader = new OFDReader(ofd)) {
            List<KeywordPosition> secondPage = KeywordExtractor.getKeyWordPositionList(
                    reader, new String[]{"报告"}, new int[]{2});
            assertEquals(1, secondPage.size(), "只检索第2页应命中一次");
            assertEquals(2, secondPage.get(0).getPage());
            assertValidPosition(secondPage.get(0), 2, "报告");

            List<KeywordPosition> firstPage = KeywordExtractor.getKeyWordPositionList(
                    reader, new String[]{"报告"}, new int[]{1});
            assertEquals(1, firstPage.size(), "只检索第1页应命中一次");
            assertEquals(1, firstPage.get(0).getPage());
        }
    }

